CREATE TABLE parked_items (id INTEGER PRIMARY KEY AUTOINCREMENT,kind INTEGER NOT NULL CHECK (kind IN (0, 1, 2)),character_slot INTEGER NOT NULL CHECK (character_slot BETWEEN -1 AND 2),location INTEGER NOT NULL CHECK (location IN (0, 1)),position INTEGER NOT NULL CHECK (position >= 0),instance_soid INTEGER NOT NULL,definition_hash INTEGER NOT NULL CHECK (definition_hash BETWEEN 1 AND 4294967295),level INTEGER NOT NULL,quantity INTEGER NOT NULL CHECK (quantity > 0),mutation_serial INTEGER NOT NULL CHECK (mutation_serial >= 0),flags INTEGER NOT NULL,socket_policy INTEGER NOT NULL CHECK (socket_policy IN (0, 1)),plug_count INTEGER NOT NULL CHECK (plug_count BETWEEN 0 AND 12),plugs BLOB NOT NULL CHECK (length(plugs) = 48),movement_ability INTEGER NOT NULL,grenade_ability INTEGER NOT NULL,super_ability INTEGER NOT NULL,melee_ability INTEGER NOT NULL,class_ability INTEGER NOT NULL,seen INTEGER NOT NULL CHECK (seen IN (0, 1))) STRICT;
